import pathlib, pandas as pd
D = pathlib.Path(__file__).resolve().parents[2] / 'data'
R = pd.read_csv(D / 'reports/theme_size_vs_duration.csv'); notes = (D / 'reports/_theme_notes.txt').read_text().split('\n')
f = lambda a, b, c: f'{a:.3f} ({b:.3f} to {c:.3f})'
L = ['# Theme level: does duration still carry the effect once size is in the model?', '',
     'Khant Phyo Wai, student ID 01323050. Exploratory, theme level, outcomes already seen; not in any record. Code: code/study2r_fix/20_theme_size_vs_duration.py (run ' + pd.Timestamp.now().strftime('%Y-%m-%d %H:%M') + ').', '',
     '## Question and method', '',
     'Study 2R (single books) found that once log2 peak size is in the model, log2 whole duration adds nothing (duration -0.022, size 0.152 per doubling). Here the same joint model is fitted on theme shifts: effect = a + b1 * log2(whole duration in weeks) + b2 * log2(whole peak ratio). Both coefficients are per doubling. Whole duration and whole peak come from the interest shift table (data/db/interest/shifts.parquet), joined to each effect row on source, theme and start week. Intervals are 95% percentile intervals of a bootstrap that resamples themes (2,000 resamples, seed 20261013). "corr(dur, peak)" is the correlation of the two predictors across shifts; "corr of coefficients" is the correlation of the two bootstrap coefficient estimates. Effects: Study 3 synthetic-control effect for months 0 to +2 (Wikipedia, narrow and middle themes, main non-seasonal analysis, one row per shift and format); Study 3b tau for months 0 to +2 (Wikipedia, narrow and middle, Seattle formats jointly, sparse and zero-count tests left out).', '']
L += notes + ['Rows that did not join to the interest shift table (72 of Study 3) are dropped. Value-level (book subject) shifts in Study 3b have no whole duration or peak in the interest table and are not included.', '']
L += ['## Results', '', '| set | shifts | themes | duration coefficient | size (peak) coefficient | corr(dur, peak) | corr of coefficients | duration alone | size alone |', '|---|---|---|---|---|---|---|---|---|']
for r in R.itertuples():
    L.append(f'| {r.set} | {r.tests} | {r.themes} | {f(r.b_dur, r.dur_lo, r.dur_hi)} | {f(r.b_peak, r.peak_lo, r.peak_hi)} | {r.corr_ld_lp:.2f} | {r.corr_coefs_boot:.2f} | {r.dur_alone:.3f} | {r.peak_alone:.3f} |')
a = R[R.set == 'Study 3 SC, print + ebook stacked'].iloc[0]; b = R[R.set == 'Study 3b tau, Seattle (all formats jointly)'].iloc[0]; m = R[R.set == 'Study 3b tau, middle only'].iloc[0]
L += ['', '"duration alone" and "size alone" are single-predictor slopes for comparison (no interval). One-sided bootstrap p-values (slope at or below 0) are in data/reports/theme_size_vs_duration.csv.', '',
      '## Reading', '',
      f'- Study 3 (print and ebook stacked, {int(a.tests)} shift-format rows in {int(a.themes)} themes): duration keeps a positive coefficient with size in the model, {f(a.b_dur, a.dur_lo, a.dur_hi)}, and its interval stays above zero in print, ebook and audiobook separately. Size does not carry the effect: {f(a.b_peak, a.peak_lo, a.peak_hi)}, a slightly negative point estimate with an interval that includes zero in every format. The two predictors correlate at {a.corr_ld_lp:.2f} (lower than the 0.72 of single books) and the two estimates trade off against each other (correlation {a.corr_coefs_boot:.2f}), which is why each is less precise than when alone.',
      f'- Study 3b (Seattle tau, {int(b.tests)} shifts in {int(b.themes)} themes): the same sign pattern but weaker: duration {f(b.b_dur, b.dur_lo, b.dur_hi)}, size {f(b.b_peak, b.peak_lo, b.peak_hi)}. Both intervals include zero in the pooled fit; duration is clearly positive in middle themes only ({f(m.b_dur, m.dur_lo, m.dur_hi)}).',
      '- So at theme level the pattern is the reverse of single books: in Study 2R size carried the effect and duration did not; for themes duration carries it (Study 3 clearly, Study 3b weakly) and size does not add. The effect at theme level is small in absolute terms (a doubling of duration is worth about 0.03 to 0.04 on the effect scale, against 0.08 per doubling of duration alone in 2R single books).',
      '- Caveats: shifts of one theme overlap in time and across narrow and middle levels, so the cluster bootstrap by theme (node) is the honest unit, and clustering by broad theme (19 clusters) gives the same sign with a wider interval (duration 0.035, 0.007 to 0.067 in Study 3; 0.021, -0.030 to 0.073 in Study 3b). The two effect scales differ (Study 3 synthetic-control effect against Study 3b log ratio), so coefficients are not comparable across the two studies in size, only in sign and relative weight. This is exploratory; no p-value here counts as a test.']
(D / 'reports/theme_size_vs_duration.md').write_text('\n'.join(L) + '\n'); print('\n'.join(L[-12:]))
